     1→import { chromium } from 'playwright';
     2→
     3→interface CLSResult {
     4→  url: string;
     5→  cls: number;
     6→  rating: 'good' | 'needs-improvement' | 'poor';
     7→  metrics: Record<string, number>;
     8→}
     9→
    10→async function measureCLS(url: string, scroll: boolean = false): Promise<CLSResult> {
    11→  const browser = await chromium.launch();
    12→  const page = await browser.newPage();
    13→  const client = await page.context().newCDPSession(page);
    14→
    15→  // Enable Performance domain
    16→  await client.send('Performance.enable');
    17→
    18→  // Navigate and wait for load
    19→  await page.goto(url, { waitUntil: 'networkidle' });
    20→
    21→  // Optional: scroll to trigger lazy-loaded content shifts
    22→  if (scroll) {
    23→    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    24→    await page.waitForTimeout(1000);
    25→    await page.evaluate(() => window.scrollTo(0, 0));
    26→    await page.waitForTimeout(500);
    27→  }
    28→
    29→  // Wait for any remaining shifts
    30→  await page.waitForTimeout(2000);
    31→
    32→  // Get all metrics including CumulativeLayoutShift
    33→  const perfMetrics = await client.send('Performance.getMetrics');
    34→
    35→  await browser.close();
    36→
    37→  // Convert metrics array to object
    38→  const metrics: Record<string, number> = {};
    39→  for (const m of perfMetrics.metrics) {
    40→    metrics[m.name] = m.value;
    41→  }
    42→
    43→  // CLS is directly available from CDP
    44→  const cls = metrics['CumulativeLayoutShift'] || 0;
    45→
    46→  // Determine rating (Google's thresholds)
    47→  let rating: 'good' | 'needs-improvement' | 'poor';
    48→  if (cls < 0.1) {
    49→    rating = 'good';
    50→  } else if (cls < 0.25) {
    51→    rating = 'needs-improvement';
    52→  } else {
    53→    rating = 'poor';
    54→  }
    55→
    56→  return {
    57→    url,
    58→    cls: Math.round(cls * 1000) / 1000,
    59→    rating,
    60→    metrics
    61→  };
    62→}
    63→
    64→// Main
    65→const url = process.argv[2] || 'http://localhost:3000';
    66→const scroll = process.argv.includes('--scroll');
    67→
    68→measureCLS(url, scroll)
    69→  .then(result => console.log(JSON.stringify(result, null, 2)))
    70→  .catch(err => {
    71→    console.error('CLS measurement failed:', err.message);
    72→    process.exit(1);
    73→  });
