     1→import { chromium } from 'playwright';
     2→import { PNG } from 'pngjs';
     3→
     4→interface FlickerResult {
     5→  url: string;
     6→  expectedTheme: string;
     7→  flickerDetected: boolean;
     8→  earlyScreenshot: string;
     9→  finalScreenshot: string;
    10→  earlyBrightness: number;
    11→  finalBrightness: number;
    12→  diagnosis: string;
    13→}
    14→
    15→function getAverageBrightness(pngBuffer: Buffer): number {
    16→  const png = PNG.sync.read(pngBuffer);
    17→  let totalBrightness = 0;
    18→  const pixelCount = png.width * png.height;
    19→
    20→  for (let y = 0; y < png.height; y++) {
    21→    for (let x = 0; x < png.width; x++) {
    22→      const idx = (png.width * y + x) << 2;
    23→      const r = png.data[idx];
    24→      const g = png.data[idx + 1];
    25→      const b = png.data[idx + 2];
    26→      // Perceived brightness formula
    27→      totalBrightness += (r * 0.299 + g * 0.587 + b * 0.114);
    28→    }
    29→  }
    30→
    31→  return totalBrightness / pixelCount;
    32→}
    33→
    34→function isLightImage(brightness: number): boolean {
    35→  return brightness > 150;
    36→}
    37→
    38→async function detectFlicker(url: string, expectedTheme: string = 'dark'): Promise<FlickerResult> {
    39→  const browser = await chromium.launch();
    40→  const context = await browser.newContext();
    41→
    42→  // Set theme preference BEFORE page loads
    43→  await context.addInitScript(`localStorage.setItem('theme', '${expectedTheme}');`);
    44→
    45→  const page = await context.newPage();
    46→
    47→  // Navigate with "commit" to catch earliest paint
    48→  await page.goto(url, { waitUntil: 'commit' });
    49→  await page.waitForTimeout(50);
    50→
    51→  // Take early screenshot and save
    52→  const earlyPath = '/tmp/flicker-early.png';
    53→  const earlyScreenshot = await page.screenshot({ path: earlyPath });
    54→
    55→  // Wait for full load
    56→  await page.waitForLoadState('networkidle');
    57→  await page.waitForTimeout(500);
    58→
    59→  // Take final screenshot and save
    60→  const finalPath = '/tmp/flicker-final.png';
    61→  const finalScreenshot = await page.screenshot({ path: finalPath });
    62→
    63→  await browser.close();
    64→
    65→  // Analyze screenshots
    66→  const earlyBrightness = getAverageBrightness(earlyScreenshot);
    67→  const finalBrightness = getAverageBrightness(finalScreenshot);
    68→
    69→  const earlyIsLight = isLightImage(earlyBrightness);
    70→  const finalIsLight = isLightImage(finalBrightness);
    71→
    72→  // Flicker detected if:
    73→  // 1. Early and final have different brightness (theme changed during load)
    74→  // 2. OR early doesn't match expected theme
    75→  const themeChanged = earlyIsLight !== finalIsLight;
    76→  const earlyMatchesExpected = expectedTheme === 'dark' ? !earlyIsLight : earlyIsLight;
    77→
    78→  let diagnosis: string;
    79→  if (themeChanged) {
    80→    diagnosis = `Theme flicker! Page went from ${earlyIsLight ? 'light' : 'dark'} to ${finalIsLight ? 'light' : 'dark'} during load`;
    81→  } else if (!earlyMatchesExpected) {
    82→    diagnosis = `Wrong initial theme: expected ${expectedTheme} but got ${earlyIsLight ? 'light' : 'dark'} at first paint`;
    83→  } else {
    84→    diagnosis = 'No flicker - correct theme from first paint';
    85→  }
    86→
    87→  return {
    88→    url,
    89→    expectedTheme,
    90→    flickerDetected: themeChanged || !earlyMatchesExpected,
    91→    earlyScreenshot: earlyPath,
    92→    finalScreenshot: finalPath,
    93→    earlyBrightness: Math.round(earlyBrightness),
    94→    finalBrightness: Math.round(finalBrightness),
    95→    diagnosis
    96→  };
    97→}
    98→
    99→// Main
   100→const url = process.argv[2] || 'http://localhost:3000';
   101→const theme = process.argv[3] || 'dark';
   102→
   103→detectFlicker(url, theme)
   104→  .then(result => console.log(JSON.stringify(result, null, 2)))
   105→  .catch(err => {
   106→    console.error('Flicker detection failed:', err.message);
   107→    process.exit(1);
   108→  });
