     1→import { chromium } from 'playwright';
     2→
     3→interface RequestTiming {
     4→  url: string;
     5→  start: number;
     6→  end?: number;
     7→}
     8→
     9→interface MeasurementResult {
    10→  url: string;
    11→  totalMs: number;
    12→  requests: { url: string; ms: number | null }[];
    13→  metrics: Record<string, number>;
    14→}
    15→
    16→async function measure(url: string): Promise<MeasurementResult> {
    17→  const browser = await chromium.launch();
    18→  const page = await browser.newPage();
    19→
    20→  // Create CDP session for low-level access
    21→  const client = await page.context().newCDPSession(page);
    22→
    23→  // Enable CDP domains we need
    24→  await client.send('Performance.enable');
    25→  await client.send('Network.enable');
    26→
    27→  // Track network requests with timestamps
    28→  const requests: RequestTiming[] = [];
    29→
    30→  // Network.requestWillBeSent fires when browser is about to send a request
    31→  // We record the URL and start timestamp to build the waterfall
    32→  client.on('Network.requestWillBeSent', (event) => {
    33→    requests.push({
    34→      url: event.request.url,
    35→      start: event.timestamp,
    36→    });
    37→  });
    38→
    39→  // Network.responseReceived fires when response headers arrive
    40→  // We find the matching request and record when it completed
    41→  client.on('Network.responseReceived', (event) => {
    42→    const req = requests.find(r => r.url === event.response.url && !r.end);
    43→    if (req) {
    44→      req.end = event.timestamp;
    45→    }
    46→  });
    47→
    48→  // Measure total page load time
    49→  const start = Date.now();
    50→  await page.goto(url, { waitUntil: 'networkidle' });
    51→  const totalMs = Date.now() - start;
    52→
    53→  // Performance.getMetrics returns Chrome's internal performance counters:
    54→  // - JSHeapUsedSize: Memory used by JavaScript objects
    55→  // - LayoutCount: Number of layout recalculations (high = layout thrashing)
    56→  // - RecalcStyleCount: Number of style recalculations
    57→  // - ScriptDuration: Total time spent executing JavaScript
    58→  // - TaskDuration: Total time spent on main thread tasks
    59→  const perfMetrics = await client.send('Performance.getMetrics');
    60→
    61→  await browser.close();
    62→
    63→  // Convert timestamps to milliseconds duration
    64→  const requestTimings = requests.map(r => ({
    65→    url: r.url,
    66→    ms: r.end ? (r.end - r.start) * 1000 : null,
    67→  }));
    68→
    69→  // Convert metrics array to object for easier reading
    70→  const metrics: Record<string, number> = {};
    71→  for (const m of perfMetrics.metrics) {
    72→    metrics[m.name] = m.value;
    73→  }
    74→
    75→  return {
    76→    url,
    77→    totalMs,
    78→    requests: requestTimings,
    79→    metrics,
    80→  };
    81→}
    82→
    83→// Main
    84→const url = process.argv[2] || 'http://localhost:3000';
    85→measure(url)
    86→  .then(result => console.log(JSON.stringify(result, null, 2)))
    87→  .catch(err => {
    88→    console.error('Measurement failed:', err.message);
    89→    process.exit(1);
    90→  });
